
const WORDS=[{"id": 0, "w": "神奇", "p": "shénqí", "t": "形容词", "m": "thần kỳ, kỳ diệu", "coll": "神奇的变化、十分神奇", "s": "一粒种子经过适当的照料逐渐长成植物这个过程令人感到神奇。"}, {"id": 1, "w": "丝瓜", "p": "sīguā", "t": "名词", "m": "(trái) mướp", "coll": "种丝瓜、丝瓜藤", "s": "院子里的丝瓜顺着架子向上攀爬不久就开出了黄色的小花。"}, {"id": 2, "w": "随即", "p": "suíjí", "t": "副词", "m": "lập tức, ngay sau đó", "coll": "随即出发、随即回应", "s": "听到消息，他随即整理好行李准备前往车站。"}, {"id": 3, "w": "株", "p": "zhū", "t": "量词", "m": "cây", "coll": "一株植物、几株幼苗", "s": "孩子们围着一株幼苗仔细观察新长出的叶子。"}, {"id": 4, "w": "粒", "p": "lì", "t": "量词", "m": "viên, hạt", "coll": "一粒种子、一粒米", "s": "她把一粒种子轻轻放进土里期待它慢慢发芽。"}, {"id": 5, "w": "土壤", "p": "tǔrǎng", "t": "名词", "m": "đất, thổ nhưỡng", "coll": "改良土壤、土壤湿度", "s": "研究人员定期记录土壤的湿度观察它与植物生长之间的关系。"}, {"id": 6, "w": "肥沃", "p": "féiwò", "t": "形容词", "m": "màu mỡ, phì nhiêu", "coll": "肥沃的土地、土壤肥沃", "s": "这里土壤肥沃村民们种植了多种蔬菜和水果。"}, {"id": 7, "w": "滋润", "p": "zīrùn", "t": "动词", "m": "làm ẩm, tưới nhuần", "coll": "雨水滋润、滋润土地", "s": "春雨滋润着田野让刚刚发芽的小草显得更加鲜绿。"}, {"id": 8, "w": "照耀", "p": "zhàoyào", "t": "动词", "m": "chiếu rọi, soi sáng", "coll": "阳光照耀、照耀大地", "s": "清晨的阳光，照耀着院子叶片上的水珠也闪起了光。"}, {"id": 9, "w": "惊讶", "p": "jīngyà", "t": "形容词", "m": "kinh ngạc, ngạc nhiên", "coll": "感到惊讶、令人惊讶", "s": "看到植物一夜之间的变化，孩子感到十分惊讶连忙叫来了老师。"}, {"id": 10, "w": "愣", "p": "lèng", "t": "动词／副词", "m": "sững sờ, ngẩn ra; cứ khăng khăng", "coll": "愣了一下、愣在原地", "s": "听到这个意外的消息，他先愣了一下随后才反应过来。"}, {"id": 11, "w": "拔苗助长", "p": "bámiáo zhùzhǎng", "t": "成语", "m": "(kéo cây lúa non để cho lúa mau lớn) nóng vội hỏng việc, đốt cháy giai đoạn", "coll": "拔苗助长、避免拔苗助长", "s": "培养孩子的能力需要尊重发展规律不能因为急于求成而拔苗助长。"}, {"id": 12, "w": "宁愿", "p": "nìngyuàn", "t": "副词", "m": "thà rằng", "coll": "宁愿等待、宁愿放弃", "s": "她宁愿多花一些时间核实，也不愿把未经证实的信息传给别人。"}, {"id": 13, "w": "疲倦", "p": "píjuàn", "t": "形容词", "m": "mệt mỏi, mệt lử", "coll": "感到疲倦、疲倦的身体", "s": "忙了一整天他感到十分疲倦便早早结束工作休息了。"}, {"id": 14, "w": "茎", "p": "jīng", "t": "名词", "m": "thân cây, cọng", "coll": "植物的茎、细长的茎", "s": "学生用放大镜仔细观察这株植物细长的茎。"}, {"id": 15, "w": "幢", "p": "zhuàng", "t": "量词", "m": "(dùng cho nhà cửa) tòa, ngôi, căn", "coll": "一幢楼、几幢房屋", "s": "河岸旁有一幢老房子门前的树已经长得很高。"}, {"id": 16, "w": "陡峭", "p": "dǒuqiào", "t": "形容词", "m": "dốc đứng, dốc", "coll": "山路陡峭、陡峭的山坡", "s": "这段山路十分陡峭大家扶着栏杆缓慢前进。"}, {"id": 17, "w": "挺拔", "p": "tǐngbá", "t": "形容词", "m": "thẳng tắp, cao chót vót", "coll": "身姿挺拔、挺拔的树木", "s": "道路两旁挺拔的树木在阳光下投下整齐的影子。"}, {"id": 18, "w": "茂盛", "p": "màoshèng", "t": "形容词", "m": "xanh tươi, tươi tốt", "coll": "枝叶茂盛、植物茂盛", "s": "经过一个春天，窗前的植物已经枝叶茂盛充满了生机。"}, {"id": 19, "w": "覆盖", "p": "fùgài", "t": "动词", "m": "che, phủ", "coll": "覆盖地面、完全覆盖", "s": "到了盛夏，爬山虎几乎覆盖了整面墙壁。"}, {"id": 20, "w": "水泥", "p": "shuǐní", "t": "名词", "m": "xi-măng", "coll": "水泥地面、水泥墙", "s": "院子里原本光秃秃的水泥墙如今已经爬满了绿色的藤蔓。"}, {"id": 21, "w": "朝气蓬勃", "p": "zhāoqì péngbó", "t": "成语", "m": "tràn đầy sức sống, tràn trề nhựa sống", "coll": "朝气蓬勃、朝气蓬勃的青年", "s": "这群朝气蓬勃的年轻人带着新的想法为社区增添了许多活力。"}, {"id": 22, "w": "生机", "p": "shēngjī", "t": "名词", "m": "sức sống, cơ hội sống", "coll": "充满生机、焕发生机", "s": "春雨过后，整个山谷重新焕发生机到处都是嫩绿的颜色。"}, {"id": 23, "w": "花瓣", "p": "huābàn", "t": "名词", "m": "cánh hoa", "coll": "一片花瓣、花瓣飘落", "s": "风吹过一片花瓣轻轻飘落停在了她的手心。"}, {"id": 24, "w": "点缀", "p": "diǎnzhuì", "t": "动词", "m": "tô điểm, điểm xuyết", "coll": "点缀花园、加以点缀", "s": "几朵黄色的小花点缀在绿叶之间使这个角落显得更加明亮。"}, {"id": 25, "w": "协调", "p": "xiétiáo", "t": "形容词／动词", "m": "nhịp nhàng, hài hòa", "coll": "动作协调、协调合作", "s": "这项活动需要大家相互配合保持动作协调才能顺利完成。"}, {"id": 26, "w": "柔和", "p": "róuhé", "t": "形容词", "m": "mềm mại, dịu dàng, nhẹ nhàng", "coll": "光线柔和、声音柔和", "s": "窗外的光线十分柔和照在书页上让人觉得安静而舒适。"}, {"id": 27, "w": "分量", "p": "fènliang", "t": "名词", "m": "trọng lượng", "coll": "分量很重、分量适中", "s": "这个袋子看着不大实际分量，却比他想象的重。"}, {"id": 28, "w": "悬挂", "p": "xuánguà", "t": "动词", "m": "treo", "coll": "悬挂标牌、悬挂在墙上", "s": "工作人员在入口处悬挂标牌提醒大家不要随意采摘植物。"}, {"id": 29, "w": "负担", "p": "fùdān", "t": "名词／动词", "m": "chịu, gánh vác, đảm nhiệm", "coll": "减轻负担、承担负担", "s": "合理安排任务有助于减轻不必要的负担让学生保持学习的积极性。"}, {"id": 30, "w": "坠", "p": "zhuì", "t": "动词", "m": "rơi, rớt", "coll": "向下坠、坠入水中", "s": "风突然变大一只熟透的果实从枝头向下坠落进了草丛。"}, {"id": 31, "w": "沉重", "p": "chénzhòng", "t": "形容词", "m": "nặng nề, nặng trĩu", "coll": "心情沉重、沉重的箱子", "s": "看完这封信，他心情十分沉重久久没有开口。"}, {"id": 32, "w": "节制", "p": "jiézhì", "t": "动词", "m": "hạn chế, có chừng mực", "coll": "有所节制、节制开支", "s": "外出旅行时，购物也应该有所节制避免带回太多用不上的东西。"}, {"id": 33, "w": "辫子", "p": "biànzi", "t": "名词", "m": "bím tóc", "coll": "扎辫子、一条辫子", "s": "外婆拿起梳子细心地给小女孩扎好了辫子。"}, {"id": 34, "w": "臂", "p": "bì", "t": "名词", "m": "cánh tay", "coll": "双臂、手臂", "s": "他张开双臂轻轻接住跑向自己的孩子。"}, {"id": 35, "w": "呵", "p": "hē", "t": "叹词", "m": "(chỉ sự kinh ngạc) a, ơ, ôi, úi chà", "coll": "呵，真美、呵，原来如此", "s": "呵，原来墙角的小花已经悄悄地开放了。"}, {"id": 36, "w": "与日俱增", "p": "yǔrì jùzēng", "t": "成语", "m": "tăng lên từng ngày", "coll": "与日俱增、信心与日俱增", "s": "随着练习的积累她对这项工作的信心也与日俱增。"}, {"id": 37, "w": "梢", "p": "shāo", "t": "名词", "m": "ngọn (cây)", "coll": "树梢、枝梢", "s": "清晨，一只小鸟停在树梢发出清脆的叫声。"}, {"id": 38, "w": "垂直", "p": "chuízhí", "t": "形容词", "m": "thẳng đứng, vuông góc", "coll": "相互垂直、垂直方向", "s": "老师在图上画出了两条相互垂直的直线。"}, {"id": 39, "w": "吊", "p": "diào", "t": "动词", "m": "treo, buộc", "coll": "吊起来、吊灯", "s": "工人使用专门的设备把沉重的材料慢慢吊了起来。"}, {"id": 40, "w": "晃", "p": "huàng", "t": "动词", "m": "lắc lư, đu đưa", "coll": "轻轻晃动、来回晃", "s": "风吹过来挂在窗边的风铃来回晃发出清脆的声音。"}, {"id": 41, "w": "断定", "p": "duàndìng", "t": "动词", "m": "nhận định, kết luận", "coll": "不能断定、断定原因", "s": "仅凭这一次观察我们还不能断定植物变化的真正原因。"}, {"id": 42, "w": "连同", "p": "liántóng", "t": "连词", "m": "kể cả", "coll": "连同材料、连同附件", "s": "请把申请表连同相关材料一起交到办公室。"}, {"id": 43, "w": "凹凸", "p": "āotū", "t": "形容词", "m": "lồi lõm, gồ ghề", "coll": "凹凸不平、表面凹凸", "s": "这条小路凹凸不平走路时需要格外留意脚下。"}, {"id": 44, "w": "修建", "p": "xiūjiàn", "t": "动词", "m": "thi công, xây dựng, xây cất", "coll": "修建道路、修建桥梁", "s": "为了方便居民出行，村里计划修建一座新的小桥。"}, {"id": 45, "w": "不可思议", "p": "bùkě sīyì", "t": "成语", "m": "không thể tưởng tượng nổi, khó mà giải thích được", "coll": "感到不可思议、不可思议的变化", "s": "看到这片原本荒凉的土地，如今变成了花园他觉得不可思议。"}, {"id": 46, "w": "徘徊", "p": "páihuái", "t": "动词", "m": "loanh quanh một chỗ, đi đi lại lại", "coll": "在门外徘徊、徘徊不前", "s": "他在门外徘徊了很久终于鼓起勇气敲响了老师的门。"}, {"id": 47, "w": "一如既往", "p": "yīrú jìwǎng", "t": "成语", "m": "trước sau như một, như thường lệ", "coll": "一如既往地支持、一如既往地努力", "s": "虽然遇到了新的困难，她仍然一如既往地努力没有放弃自己的计划。"}];
const CHUNKS=[["一粒种子", "经过适当的照料", "逐渐长成植物", "这个过程令人感到神奇。"], ["院子里的丝瓜", "顺着架子向上攀爬", "不久", "就开出了黄色的小花。"], ["听到消息，", "他", "随即整理好行李", "准备前往车站。"], ["孩子们", "围着一株幼苗", "仔细观察", "新长出的叶子。"], ["她", "把一粒种子", "轻轻放进土里", "期待它慢慢发芽。"], ["研究人员", "定期记录土壤的湿度", "观察", "它与植物生长之间的关系。"], ["这里", "土壤肥沃", "村民们", "种植了多种蔬菜和水果。"], ["春雨", "滋润着田野", "让刚刚发芽的小草", "显得更加鲜绿。"], ["清晨的阳光，", "照耀着院子", "叶片上的水珠", "也闪起了光。"], ["看到植物一夜之间的变化，", "孩子", "感到十分惊讶", "连忙叫来了老师。"], ["听到这个意外的消息，", "他", "先愣了一下", "随后才反应过来。"], ["培养孩子的能力", "需要尊重发展规律", "不能", "因为急于求成而拔苗助长。"], ["她", "宁愿多花一些时间核实，", "也不愿", "把未经证实的信息传给别人。"], ["忙了一整天", "他", "感到十分疲倦", "便早早结束工作休息了。"], ["学生", "用放大镜", "仔细观察", "这株植物细长的茎。"], ["河岸旁", "有一幢老房子", "门前的树", "已经长得很高。"], ["这段山路", "十分陡峭", "大家", "扶着栏杆缓慢前进。"], ["道路两旁", "挺拔的树木", "在阳光下", "投下整齐的影子。"], ["经过一个春天，", "窗前的植物", "已经枝叶茂盛", "充满了生机。"], ["到了盛夏，", "爬山虎", "几乎覆盖了", "整面墙壁。"], ["院子里", "原本光秃秃的水泥墙", "如今", "已经爬满了绿色的藤蔓。"], ["这群朝气蓬勃的年轻人", "带着新的想法", "为社区", "增添了许多活力。"], ["春雨过后，", "整个山谷", "重新焕发生机", "到处都是嫩绿的颜色。"], ["风吹过", "一片花瓣", "轻轻飘落", "停在了她的手心。"], ["几朵黄色的小花", "点缀在绿叶之间", "使这个角落", "显得更加明亮。"], ["这项活动", "需要大家相互配合", "保持动作协调", "才能顺利完成。"], ["窗外的光线", "十分柔和", "照在书页上", "让人觉得安静而舒适。"], ["这个袋子", "看着不大", "实际分量，", "却比他想象的重。"], ["工作人员", "在入口处悬挂标牌", "提醒大家", "不要随意采摘植物。"], ["合理安排任务", "有助于", "减轻不必要的负担", "让学生保持学习的积极性。"], ["风突然变大", "一只熟透的果实", "从枝头向下坠", "落进了草丛。"], ["看完这封信，", "他", "心情十分沉重", "久久没有开口。"], ["外出旅行时，", "购物", "也应该有所节制", "避免带回太多用不上的东西。"], ["外婆", "拿起梳子", "细心地", "给小女孩扎好了辫子。"], ["他", "张开双臂", "轻轻接住", "跑向自己的孩子。"], ["呵，", "原来墙角的小花", "已经", "悄悄地开放了。"], ["随着练习的积累", "她", "对这项工作的信心", "也与日俱增。"], ["清晨，", "一只小鸟", "停在树梢", "发出清脆的叫声。"], ["老师", "在图上", "画出了", "两条相互垂直的直线。"], ["工人", "使用专门的设备", "把沉重的材料", "慢慢吊了起来。"], ["风吹过来", "挂在窗边的风铃", "来回晃", "发出清脆的声音。"], ["仅凭这一次观察", "我们", "还不能断定", "植物变化的真正原因。"], ["请", "把申请表", "连同相关材料", "一起交到办公室。"], ["这条小路", "凹凸不平", "走路时", "需要格外留意脚下。"], ["为了方便居民出行，", "村里", "计划修建", "一座新的小桥。"], ["看到这片原本荒凉的土地，", "如今变成了花园", "他", "觉得不可思议。"], ["他", "在门外徘徊了很久", "终于鼓起勇气", "敲响了老师的门。"], ["虽然遇到了新的困难，", "她", "仍然一如既往地努力", "没有放弃自己的计划。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai18-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#47;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/48 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),48)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共48个词语，点击 ↗ 学习该词语',totalLearned()+'/48 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===47;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<47){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:7};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课48个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课48个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [3, 4, 15], "5": [14, 27, 33], "8": [7, 24, 44], "11": [1, 14, 33], "14": [5, 27, 33], "17": [5, 27, 33], "20": [1, 14, 33], "23": [5, 27, 33], "26": [5, 27, 33], "29": [14, 20, 33], "32": [1, 14, 33], "35": [1, 14, 33], "38": [1, 14, 33], "41": [7, 24, 44], "44": [7, 24, 41], "47": [1, 14, 33]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如音频暂时无法播放，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的48个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第18课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第18课学习进度','第18课 · 48个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 48</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第18课';$('ntc-bookmark').textContent=student?total+'/48 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第18课学习进度</div><div style="padding:0 10px">'+total+'/48 个已学词语'+meter(total,48)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"神奇":"data:audio/mpeg;base64,","一粒种子经过适当的照料逐渐长成植物这个过程令人感到神奇。":"data:audio/mpeg;base64,","丝瓜":"data:audio/mpeg;base64,","院子里的丝瓜顺着架子向上攀爬不久就开出了黄色的小花。":"data:audio/mpeg;base64,","随即":"data:audio/mpeg;base64,","听到消息，他随即整理好行李准备前往车站。":"data:audio/mpeg;base64,","株":"data:audio/mpeg;base64,","孩子们围着一株幼苗仔细观察新长出的叶子。":"data:audio/mpeg;base64,","粒":"data:audio/mpeg;base64,","她把一粒种子轻轻放进土里期待它慢慢发芽。":"data:audio/mpeg;base64,","土壤":"data:audio/mpeg;base64,","研究人员定期记录土壤的湿度观察它与植物生长之间的关系。":"data:audio/mpeg;base64,","肥沃":"data:audio/mpeg;base64,","这里土壤肥沃村民们种植了多种蔬菜和水果。":"data:audio/mpeg;base64,","滋润":"data:audio/mpeg;base64,","春雨滋润着田野让刚刚发芽的小草显得更加鲜绿。":"data:audio/mpeg;base64,","照耀":"data:audio/mpeg;base64,","清晨的阳光，照耀着院子叶片上的水珠也闪起了光。":"data:audio/mpeg;base64,","惊讶":"data:audio/mpeg;base64,","看到植物一夜之间的变化，孩子感到十分惊讶连忙叫来了老师。":"data:audio/mpeg;base64,","愣":"data:audio/mpeg;base64,","听到这个意外的消息，他先愣了一下随后才反应过来。":"data:audio/mpeg;base64,","拔苗助长":"data:audio/mpeg;base64,","培养孩子的能力需要尊重发展规律不能因为急于求成而拔苗助长。":"data:audio/mpeg;base64,","宁愿":"data:audio/mpeg;base64,","她宁愿多花一些时间核实，也不愿把未经证实的信息传给别人。":"data:audio/mpeg;base64,","疲倦":"data:audio/mpeg;base64,","忙了一整天他感到十分疲倦便早早结束工作休息了。":"data:audio/mpeg;base64,","茎":"data:audio/mpeg;base64,","学生用放大镜仔细观察这株植物细长的茎。":"data:audio/mpeg;base64,","幢":"data:audio/mpeg;base64,","河岸旁有一幢老房子门前的树已经长得很高。":"data:audio/mpeg;base64,","陡峭":"data:audio/mpeg;base64,","这段山路十分陡峭大家扶着栏杆缓慢前进。":"data:audio/mpeg;base64,","挺拔":"data:audio/mpeg;base64,","道路两旁挺拔的树木在阳光下投下整齐的影子。":"data:audio/mpeg;base64,","茂盛":"data:audio/mpeg;base64,","经过一个春天，窗前的植物已经枝叶茂盛充满了生机。":"data:audio/mpeg;base64,","覆盖":"data:audio/mpeg;base64,","到了盛夏，爬山虎几乎覆盖了整面墙壁。":"data:audio/mpeg;base64,","水泥":"data:audio/mpeg;base64,","院子里原本光秃秃的水泥墙如今已经爬满了绿色的藤蔓。":"data:audio/mpeg;base64,","朝气蓬勃":"data:audio/mpeg;base64,","这群朝气蓬勃的年轻人带着新的想法为社区增添了许多活力。":"data:audio/mpeg;base64,","生机":"data:audio/mpeg;base64,","春雨过后，整个山谷重新焕发生机到处都是嫩绿的颜色。":"data:audio/mpeg;base64,","花瓣":"data:audio/mpeg;base64,","风吹过一片花瓣轻轻飘落停在了她的手心。":"data:audio/mpeg;base64,","点缀":"data:audio/mpeg;base64,","几朵黄色的小花点缀在绿叶之间使这个角落显得更加明亮。":"data:audio/mpeg;base64,","协调":"data:audio/mpeg;base64,","这项活动需要大家相互配合保持动作协调才能顺利完成。":"data:audio/mpeg;base64,","柔和":"data:audio/mpeg;base64,","窗外的光线十分柔和照在书页上让人觉得安静而舒适。":"data:audio/mpeg;base64,","分量":"data:audio/mpeg;base64,","这个袋子看着不大实际分量，却比他想象的重。":"data:audio/mpeg;base64,","悬挂":"data:audio/mpeg;base64,","工作人员在入口处悬挂标牌提醒大家不要随意采摘植物。":"data:audio/mpeg;base64,","负担":"data:audio/mpeg;base64,","合理安排任务有助于减轻不必要的负担让学生保持学习的积极性。":"data:audio/mpeg;base64,","坠":"data:audio/mpeg;base64,","风突然变大一只熟透的果实从枝头向下坠落进了草丛。":"data:audio/mpeg;base64,","沉重":"data:audio/mpeg;base64,","看完这封信，他心情十分沉重久久没有开口。":"data:audio/mpeg;base64,","节制":"data:audio/mpeg;base64,","外出旅行时，购物也应该有所节制避免带回太多用不上的东西。":"data:audio/mpeg;base64,","辫子":"data:audio/mpeg;base64,","外婆拿起梳子细心地给小女孩扎好了辫子。":"data:audio/mpeg;base64,","臂":"data:audio/mpeg;base64,","他张开双臂轻轻接住跑向自己的孩子。":"data:audio/mpeg;base64,","呵":"data:audio/mpeg;base64,","呵，原来墙角的小花已经悄悄地开放了。":"data:audio/mpeg;base64,","与日俱增":"data:audio/mpeg;base64,","随着练习的积累她对这项工作的信心也与日俱增。":"data:audio/mpeg;base64,","梢":"data:audio/mpeg;base64,","清晨，一只小鸟停在树梢发出清脆的叫声。":"data:audio/mpeg;base64,","垂直":"data:audio/mpeg;base64,","老师在图上画出了两条相互垂直的直线。":"data:audio/mpeg;base64,","吊":"data:audio/mpeg;base64,","工人使用专门的设备把沉重的材料慢慢吊了起来。":"data:audio/mpeg;base64,","晃":"data:audio/mpeg;base64,","风吹过来挂在窗边的风铃来回晃发出清脆的声音。":"data:audio/mpeg;base64,","断定":"data:audio/mpeg;base64,","仅凭这一次观察我们还不能断定植物变化的真正原因。":"data:audio/mpeg;base64,","连同":"data:audio/mpeg;base64,","请把申请表连同相关材料一起交到办公室。":"data:audio/mpeg;base64,","凹凸":"data:audio/mpeg;base64,","这条小路凹凸不平走路时需要格外留意脚下。":"data:audio/mpeg;base64,","修建":"data:audio/mpeg;base64,","为了方便居民出行，村里计划修建一座新的小桥。":"data:audio/mpeg;base64,","不可思议":"data:audio/mpeg;base64,","看到这片原本荒凉的土地，如今变成了花园他觉得不可思议。":"data:audio/mpeg;base64,","徘徊":"data:audio/mpeg;base64,","他在门外徘徊了很久终于鼓起勇气敲响了老师的门。":"data:audio/mpeg;base64,","一如既往":"data:audio/mpeg;base64,","虽然遇到了新的困难，她仍然一如既往地努力没有放弃自己的计划。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai18-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai18_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai18-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=48)||!p.memory)throw Error();if(!confirm('恢复第18课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<48;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<48&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第18课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

